const COIN_RATES510={cp:1,sp:10,ep:50,gp:100,pp:1000};
function price510(cp){if(cp===0)return '0 PO';if(cp>=100)return (cp/100).toLocaleString('pt-BR',{maximumFractionDigits:2})+' PO';if(cp%10===0)return cp/10+' PP';return cp+' PC';}
function walletCoins510(){const out={};for(const [key,rate]of Object.entries(COIN_RATES510)){const n=coinValue(key),copper=n*rate;if(!Number.isFinite(n)||n<0||!Number.isSafeInteger(Math.round(copper))||Math.abs(copper-Math.round(copper))>1e-6||key!=='gp'&&!Number.isInteger(n))throw Error('Confira os valores das moedas na carteira.');out[key]=n;}return out;}
function walletTotal510(coins=walletCoins510()){const total=Object.entries(COIN_RATES510).reduce((n,[key,rate])=>n+Math.round(coins[key]*rate),0);if(!Number.isSafeInteger(total))throw Error('O saldo da carteira é muito alto.');return total;}
function debitCoins510(coins,cost){if(!Number.isSafeInteger(cost)||cost<0||walletTotal510(coins)<cost)throw Error('Saldo insuficiente para esta compra.');const result={...coins};let remaining=cost;
 // Preserve existing denominations, spend small coins first, then break a larger coin for change.
 for(const [key,rate]of Object.entries(COIN_RATES510)){const count=Math.min(Math.floor(result[key]),Math.floor(remaining/rate));result[key]-=count;remaining-=count*rate;}
 if(remaining){const key=Object.keys(COIN_RATES510).find(k=>result[k]>=1&&COIN_RATES510[k]>remaining);if(key){result[key]--;let change=COIN_RATES510[key]-remaining;remaining=0;for(const k of ['gp','sp','cp']){const n=Math.floor(change/COIN_RATES510[k]);result[k]+=n;change-=n*COIN_RATES510[k];}}else if(result.gp>0&&Math.round(result.gp*100)>=remaining){const fractional=Math.round(result.gp*100)-remaining;result.gp=0;result.sp+=Math.floor(fractional/10);result.cp+=fractional%10;remaining=0;}}
 if(remaining||walletTotal510(result)!==walletTotal510(coins)-cost)throw Error('Não foi possível calcular o troco. Confira as moedas.');return result;}
