function gifEditor512(scope){return `<section class="roll-gif-editor512" data-gif-scope512="${scope}" data-gif-char512="${esc(c().id)}"><h3>GIFs no resultado da rolagem</h3><p class="muted">Escolha um GIF padrão ou um específico. O GIF aparece somente quando o resultado é revelado, dentro do quadro de resultado.</p><label>Rolagem<select id="gif-target512" aria-label="Rolagem para GIF" onchange="refreshGifName512()">${gifTargets512(scope).map(([key,name])=>`<option value="${esc(key)}">${esc(name)}</option>`).join('')}</select></label><p id="gif-name512" class="gif-name512"></p><div class="actions"><button onclick="document.querySelector('#gif-file512').click()">Adicionar ou trocar GIF</button><button id="gif-remove512" onclick="removeRollGif512()">Remover GIF</button></div><input id="gif-file512" type="file" hidden accept="image/gif" onchange="uploadRollGif512(event)"><p class="muted">Arquivo GIF de até 10 MB. Um GIF específico tem prioridade sobre o padrão.</p><p id="gif-status512" role="status"></p></section>`;}
function gifEditorContext512(){const root=document.querySelector('#play-dialog[open] .roll-gif-editor512');if(!root||root.dataset.gifChar512!==c()?.id)return null;const scope=root.dataset.gifScope512,key=root.querySelector('#gif-target512')?.value;if(!gifTargets512(scope).some(([v])=>v===key))return null;return {root,scope,key,char:c()};}
function refreshGifName512(){const ctx=gifEditorContext512();if(!ctx)return;const media=ctx.char.play?.rollGifs512?.[ctx.key];ctx.root.querySelector('#gif-name512').textContent=media?'GIF: '+String(media.name||'Arquivo salvo'):'Nenhum GIF específico. O padrão será usado, se houver.';ctx.root.querySelector('#gif-remove512').disabled=!media;ctx.root.querySelector('#gif-status512').textContent='';}
