openInventory526=function(id){detailsBefore535(id);const item=playState().inventory.find(e=>e.id===id);if(!item)return;const root=document.querySelector('#play-body');if(!item.bookId&&!inventoryCatalog526(item)&&!equipWeapon535(item)&&!armorItemMode54(item))root?.insertAdjacentHTML('beforeend',`<label>Tipo do acessório personalizado<select onchange="setEquipType535(${inventoryArg526(id)},this.value)"><option value="">Não equipável</option>${Object.entries(EQUIP_SLOTS535).filter(([key])=>!['armor','left','right'].includes(key)).map(([key,name])=>`<option value="${key}" ${item.equipType535===key?'selected':''}>${name}</option>`).join('')}</select></label>`);};
