const managedEquip536=inventoryEquip;
inventoryEquip=function(id){if(!equipmentEnabled536())return equipWithoutManager536(id);return managedEquip536(id);};
const managedCalc536=calcSet;
calcSet=function(key,value){return equipmentEnabled536()?managedCalc536(key,value):calcWithoutManager536(key,value);};
const managedView536=inventoryView;
inventoryView=function(){if(equipmentEnabled536())return managedView536();const box=document.createElement('div');box.innerHTML=inventoryBefore535();const weight=box.querySelector('.inventory-weight526');if(weight)weight.innerHTML='Peso total: <b>'+inventoryNumber526(playState().inventory.reduce((n,e)=>n+Number(e.quantity||0)*Number(e.weight||0),0))+' lb</b>';return box.innerHTML;};
const managedRequest536=requestEquip535;
requestEquip535=function(id,slot){if(equipmentEnabled536())return managedRequest536(id,slot);};
const managedConfirm536=confirmEquip535;
confirmEquip535=function(){if(equipmentEnabled536())return managedConfirm536();};
function setEquipmentEnabled536(on){const before=SETTINGS48.equipmentManager536;SETTINGS48.equipmentManager536=!!on;try{saveSettings48();}catch{SETTINGS48.equipmentManager536=before;toast('Não foi possível salvar a configuração.');return openSettings48();}equipPending535=null;render();openSettings48();}
const settingsBefore536=openSettings48;
openSettings48=function(){settingsBefore536();const block=document.createElement('div');block.className='equipment-option536';block.innerHTML='<label class="calc-option"><input id="equipment-manager536" type="checkbox" '+(equipmentEnabled536()?'checked':'')+' onchange="setEquipmentEnabled536(this.checked)"><span>Gerenciador de equipamentos e limites de mãos/carga</span></label><p class="muted">Ativado: exibe a referência corporal e organiza os espaços equipados. Desativado: permite equipar livremente pelo Inventário. Ao reativar, itens excedentes ou incompatíveis ficam guardados no inventário, sem serem excluídos.</p>';const body=document.querySelector('#play-body'),backup=body.querySelector('.backup-parchment');if(backup)backup.before(block);else body.append(block);};


