function libName537(e){return SETTINGS48.language==='en'?e?.name||'':BOOK_PT444[e?.id]?.name||e?.name||'';}
function libFeatureName537(f){return SETTINGS48.language==='en'?f.name:FEATURE_PT435[f.id]?.name||({'Ability Score Improvement':'Aumento de Atributo','Epic Boon':'Dádiva Épica'}[f.name])||f.name;}
function libText537(e){return SETTINGS48.language==='en'?e.text:BOOK_PT444[e.id]?.text||e.text;}
function libFacts537(rows){return `<dl class="lib-facts537">${rows.filter(r=>r[1]!==undefined&&r[1]!==null&&r[1]!=='').map(([k,v])=>`<div class="${String(v).replace(/<[^>]*>/g,'').length>70?'lib-fact-wide537':''}"><dt>${esc(k)}</dt><dd>${v}</dd></div>`).join('')}</dl>`;}
