const DREAM_INTRO2014_557='Feitiçaria dos Sonhos · Feiticeiro de D&D 2014.\n\nA magia dos sonhos permite trazer visões da mente adormecida para o mundo desperto. Você recebe Magias da Feitiçaria dos Sonhos e Destino dos Sonhos no 1º nível de Feiticeiro. Os demais benefícios chegam nos níveis 6, 14 e 18, conforme o livro Planegea. Esta opção não concede Feitiçaria Inata.';
function legacyFeature557(key,name,pt,text,level){const id='sorc2014-557:'+key;FEATURE_PT435[id]={original:name,name:pt,source:text,text,level,cls:'Feiticeiro'};return {id,name,text,level};}
const META_TEXT2014_557='No 3º nível, escolha duas opções de Metamagia. Escolha mais uma no 10º nível e outra no 17º nível, totalizando quatro. Você pode aplicar apenas uma opção à mesma conjuração, salvo quando a própria opção permitir uma combinação. Os custos são pagos com Pontos de Feitiçaria.\n\n• Magia Cuidadosa (1 ponto): escolha até seu modificador de Carisma, no mínimo uma criatura, entre os alvos obrigados a realizar uma salvaguarda. As escolhidas passam nessa salvaguarda.\n\n• Magia Distante (1 ponto): dobre um alcance de pelo menos 5 pés; um alcance de Toque passa a 30 pés.\n\n• Magia Potencializada (1 ponto): role novamente até seu modificador de Carisma de dados de dano, no mínimo um dado, e use os novos resultados. Pode ser combinada com outra Metamagia.\n\n• Magia Estendida (1 ponto): dobre a duração de uma magia que dure pelo menos 1 minuto, até o limite de 24 horas.\n\n• Magia Aumentada (3 pontos): um alvo tem Desvantagem na primeira salvaguarda contra a magia.\n\n• Magia Acelerada (2 pontos): uma magia com tempo de conjuração de uma Ação passa a usar uma Ação Bônus nessa conjuração.\n\n• Magia Sutil (1 ponto): a conjuração dispensa componentes Verbais e Somáticos. Componentes Materiais continuam necessários.\n\n• Magia Duplicada (pontos iguais ao círculo, ou 1 para um truque): acrescente um segundo alvo no alcance a uma magia que, no círculo utilizado, seja incapaz de afetar mais de uma criatura e não tenha alcance Pessoal.';
const LEGACY_BASE557=[
 legacyFeature557('casting','Spellcasting','Conjuração','Você conhece quatro truques e duas magias de 1º círculo da lista de Feiticeiro no 1º nível. Seu atributo de conjuração é Carisma. Sua CD é 8 + Bônus de Proficiência + modificador de Carisma; seu Ataque de Magia usa Bônus de Proficiência + modificador de Carisma. Pode usar um foco arcano.\n\nAs magias são conhecidas, sem preparação diária. Ao ganhar um nível de Feiticeiro, você pode substituir uma magia conhecida por outra da lista para a qual possua espaços de magia. As quantidades de magias conhecidas seguem a tabela de 2014. Truques: quatro inicialmente, cinco a partir do 4º nível e seis a partir do 10º. Recupera os espaços gastos ao terminar um Descanso Longo.\n\nO catálogo compartilhado de magias do Códice continua disponível; esta opção altera a progressão da classe, sem substituir todas as descrições de magias pelas versões de 2014.',1),
 legacyFeature557('origin','Sorcerer Subclass','Origem de Feitiçaria','Escolha sua subclasse no 1º nível de Feiticeiro. Ela concede novos benefícios nos níveis 6, 14 e 18. Feitiçaria dos Sonhos usa os níveis originais do livro Planegea; Linhagem Dracônica usa a progressão de 2014.',1),
 legacyFeature557('font','Font of Magic','Fonte de Magia','A partir do 2º nível, seu máximo de Pontos de Feitiçaria é igual ao seu nível de Feiticeiro. Recupera todos os pontos gastos ao terminar um Descanso Longo.\n\nComo uma Ação Bônus, pode gastar pontos para criar um espaço: 1º círculo custa 2; 2º custa 3; 3º custa 5; 4º custa 6; 5º custa 7. Esses espaços extras desaparecem após um Descanso Longo.\n\nComo uma Ação Bônus, também pode gastar um espaço para recuperar pontos em quantidade igual ao círculo desse espaço, sem superar seu máximo.',2),
 ...[3,10,17].map(n=>legacyFeature557('meta-'+n,'Metamagic','Metamagia',META_TEXT2014_557,n)),
 ...[4,8,12,16,19].map(n=>legacyFeature557('asi-'+n,'Ability Score Improvement','Aumento de Atributo','Aumente um atributo em 2 ou dois atributos diferentes em 1, sem ultrapassar 20. Se sua mesa usar talentos, pode escolher um talento em vez desse aumento. No 19º nível, o Feiticeiro de 2014 recebe este aumento; não recebe automaticamente uma Dádiva Épica.',n)),
 legacyFeature557('restoration','Sorcerous Restoration','Restauração Feiticeira','No 20º nível, você recupera 4 Pontos de Feitiçaria gastos ao terminar um Descanso Curto, sem ultrapassar seu máximo.',20)
];
const DRACONIC_FEATURES2014_557=[
 legacyFeature557('ancestor','Dragon Ancestor','Ancestral Dracônico','Escolha o tipo de dragão de sua ancestralidade: Preto ou Cobre (Ácido); Azul ou Bronze (Elétrico); Latão, Ouro ou Vermelho (Ígneo); Verde (Veneno); Prata ou Branco (Gélido). O tipo de dano é usado por seus benefícios posteriores.\n\nVocê fala, lê e escreve Dracônico. Ao realizar um teste de Carisma para interagir com dragões, dobre seu Bônus de Proficiência se ele for aplicável ao teste.',1),
 legacyFeature557('resilience','Draconic Resilience','Resiliência Dracônica','Seus PV máximos aumentam em 1 para cada nível de Feiticeiro, começando no 1º nível. Enquanto não usa armadura, sua CA base é 13 + modificador de Destreza.',1),
 legacyFeature557('affinity','Elemental Affinity','Afinidade Elemental','No 6º nível, ao conjurar uma magia que cause dano do tipo associado ao seu ancestral, adicione seu modificador de Carisma a uma jogada de dano dessa magia. Na mesma ocasião, pode gastar 1 Ponto de Feitiçaria para receber Resistência a esse tipo de dano por 1 hora.',6),
 legacyFeature557('wings','Dragon Wings','Asas de Dragão','No 14º nível, como uma Ação Bônus no seu turno, você pode manifestar asas de dragão e adquirir deslocamento de voo igual ao seu deslocamento atual. Elas duram até serem dispensadas com outra Ação Bônus. Uma armadura deve ter sido adaptada para acomodar as asas; roupas inadequadas podem ser destruídas quando elas surgem.',14),
 legacyFeature557('presence','Draconic Presence','Presença Dracônica','No 18º nível, como uma Ação, gaste 5 Pontos de Feitiçaria para criar uma aura de admiração ou medo de 60 pés por até 1 minuto, exigindo Concentração como uma magia. Uma criatura hostil que começar seu turno nessa aura faz uma salvaguarda de Sabedoria contra sua CD de magia. Se falhar, fica Enfeitiçada (admiração) ou Amedrontada (medo), à sua escolha ao criar a aura, até a aura acabar. Se passar, fica imune a esta aura por 24 horas.',18)
];
